// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"ibandronsaeure":{"wirkmechanismus":"Bremst den Knochenabbau, sodass die Knochendichte zunimmt und das Bruchrisiko sinkt. Ibandronsäure ist ein stickstoffhaltiges Bisphosphonat, das sich an das Knochenmineral anlagert und von den knochenabbauenden Zellen (Osteoklasten) aufgenommen wird. Dort hemmt es die Farnesylpyrophosphat-Synthase und unterdrückt so deren Aktivität. Die starke Bindung an den Knochen erlaubt eine Einnahme einmal pro Monat oder eine Spritze alle drei Monate.","nebenwirkungen":{"haeufig":["Sodbrennen, Verdauungsbeschwerden, Gastritis, Refluxösophagitis","Bauchschmerzen, Durchfall, Übelkeit","Kopfschmerzen","Hautausschlag","Gelenk-, Muskel- und Knochenschmerzen, Muskelkrämpfe","Grippeähnliche Beschwerden (Akute-Phase-Reaktion), vor allem nach der ersten Gabe","Müdigkeit","Hypokalzämie (Calciummangel) bei hoch dosierter Infusion"],"gelegentlich":["Schwindel","Entzündung oder Geschwüre der Speiseröhre, Schluckbeschwerden, Erbrechen","Rückenschmerzen","Venenreizung an der Injektionsstelle"],"selten":["Überempfindlichkeitsreaktionen, Angioödem, Nesselsucht","Augenentzündungen (Uveitis, Skleritis)","Atypische Oberschenkelbrüche"],"sehrSelten":["Kiefernekrose (Absterben von Kieferknochen)","Osteonekrose des äusseren Gehörgangs","Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, Erythema multiforme)"]},"schwangerschaft":"Nicht anwenden.","stillzeit":"Nicht anwenden.","hinweise":["Monatstablette immer am gleichen Kalendertag morgens nüchtern mit einem vollen Glas Leitungswasser unzerkaut einnehmen; danach 60 Minuten aufrecht bleiben und nichts essen, trinken oder einnehmen.","Bei Spritze oder Infusion werden vor jeder Gabe die Nierenwerte bestimmt.","Für ausreichend Calcium und Vitamin D sorgen; vor Beginn Zahnstatus kontrollieren und auf gute Mundhygiene achten.","Neue Oberschenkel-, Leisten- oder Ohrenschmerzen ärztlich abklären lassen."],"darreichung":["Filmtabletten","Injektionslösung (Fertigspritze)","Infusionskonzentrat"]},"ibrutinib":{"wirkmechanismus":"Schaltet ein Signalprotein ab, das bösartige B-Lymphozyten zum Überleben und Wachsen brauchen. Ibrutinib bindet kovalent und irreversibel an die Bruton-Tyrosinkinase (BTK), ein Schlüsselenzym des B-Zell-Rezeptor-Signalwegs. Dadurch werden Vermehrung und Überleben der Tumorzellen sowie ihr Einwandern in Lymphknoten und Knochenmark gehemmt; vorübergehend steigt deshalb oft die Lymphozytenzahl im Blut. Die zusätzliche Hemmung der Blutplättchenfunktion erklärt das erhöhte Blutungsrisiko.","nebenwirkungen":{"sehrHaeufig":["Infektionen: Lungenentzündung, obere Atemwege, Haut","Neutropenie, Thrombozytopenie","Blutungen, blaue Flecken","Bluthochdruck","Durchfall, Übelkeit, Erbrechen, Stomatitis, Verstopfung","Hautausschlag","Gelenk-, Muskel- und Knochenschmerzen, Muskelkrämpfe","Fieber, periphere Ödeme, Schwindel, Kopfschmerzen"],"haeufig":["Vorhofflimmern","Herzschwäche","Sepsis, Harnwegsinfekte, Sinusitis","Weisser Hautkrebs (Basalzell- und Plattenepithelkarzinom)","Febrile Neutropenie, Leukozytose","Nasenbluten, punktförmige Hautblutungen (Petechien)","Interstitielle Lungenerkrankung","Verschwommenes Sehen, Nesselsucht, brüchige Nägel, periphere Neuropathie, erhöhte Harnsäure"],"gelegentlich":["Ventrikuläre Tachyarrhythmien, Herzstillstand","Subdurales Hämatom (Blutung unter der harten Hirnhaut)","Opportunistische Infektionen (z. B. Pneumocystis, Pilze)","Leukostase-Syndrom","Tumorlyse-Syndrom","Angioödem, neutrophile Dermatosen, Pannikulitis"],"unbekannt":["Hepatitis-B-Reaktivierung","Leberversagen","Progressive multifokale Leukenzephalopathie (PML)","Stevens-Johnson-Syndrom"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen müssen während und bis 3 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Einmal täglich zur gleichen Zeit unzerkaut mit Wasser schlucken; Grapefruit und Bitterorangen meiden.","Vor geplanten Operationen oder Zahnbehandlungen informieren: die Einnahme wird meist 3–7 Tage vorher und nachher unterbrochen.","Herzklopfen, unregelmässigen Puls, Atemnot oder Ohnmacht sofort melden; Blutdruck regelmässig messen.","Blutverdünner, Schmerzmittel (NSAR) sowie Fischöl- oder Vitamin-E-Präparate nur nach ärztlicher Rücksprache."],"darreichung":["Filmtabletten","Kapseln"]},"ibuprofen":{"wirkmechanismus":"Lindert Schmerzen, senkt Fieber und hemmt Entzündungen, indem es die Bildung von Prostaglandinen verhindert. Ibuprofen hemmt reversibel die Cyclooxygenasen COX-1 und COX-2. Die Hemmung der Blutplättchen ist im Gegensatz zu Acetylsalicylsäure nur vorübergehend; regelmässig eingenommen kann Ibuprofen aber die herzschützende Wirkung niedrig dosierter Acetylsalicylsäure abschwächen.","nebenwirkungen":{"haeufig":["Dyspepsie (Verdauungsbeschwerden), Übelkeit, Erbrechen, Bauchschmerzen","Durchfall, Blähungen, Verstopfung","Magen-Darm-Blutungen mit Teerstuhl oder Bluterbrechen (bei hohen, rezeptpflichtigen Dosen)","Kopfschmerzen, Schwindel","Müdigkeit","Hautausschlag"],"gelegentlich":["Überempfindlichkeitsreaktionen mit Nesselsucht, Juckreiz, Angioödem","Gastritis, Magen-Darm-Geschwüre, Durchbruch (Perforation)","Asthmaanfälle, Bronchospasmus, Atemnot","Schlaflosigkeit, Angst, Kribbeln, Schläfrigkeit","Sehstörungen, Hörstörungen, Ohrensausen (Tinnitus)","Hepatitis, Gelbsucht, veränderte Leberwerte","Lichtempfindlichkeit der Haut","Nierenschäden"],"selten":["Blutbildstörungen bis Agranulozytose (Ausfall der weissen Blutkörperchen) und aplastische Anämie","Anaphylaxie (schwere allergische Reaktion)","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)","Depression, Verwirrtheit","Ödeme (Wassereinlagerungen)","Sehnervenentzündung"],"sehrSelten":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme)","Leberversagen","Herzinsuffizienz, Herzinfarkt","Bluthochdruck","Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["DRESS (Arzneimittelreaktion mit Eosinophilie und Organbeteiligung)","Akute generalisierte exanthematische Pustulose (AGEP)","Kounis-Syndrom (allergisch ausgelöster Herzinfarkt)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich (ab der 20. Woche Risiko für Nierenschäden beim Kind und Fruchtwassermangel). Im letzten Drittel kontraindiziert.","stillzeit":"Geht nur in geringen Mengen in die Muttermilch über; eine kurzfristige Einnahme in üblicher Dosis ist in der Regel vertretbar.","hinweise":["In der Selbstmedikation höchstens 1200 mg pro Tag und ohne ärztlichen Rat nur wenige Tage einnehmen; bei Kindern richtet sich die Dosis nach dem Körpergewicht.","Bei Magenbeschwerden zu oder nach einer Mahlzeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","Wer niedrig dosierte Acetylsalicylsäure zum Herzschutz nimmt, sollte Ibuprofen nicht regelmässig ohne ärztliche Rücksprache einnehmen.","Bei Kindern mit Erbrechen, Durchfall oder ungenügendem Trinken auf genügend Flüssigkeit achten (Gefahr von Nierenschäden)."],"darreichung":["Filmtabletten","Weichkapseln","Granulat (Beutel)","Suspension (Sirup)","Zäpfchen"]},"icatibant":{"wirkmechanismus":"Blockiert die Wirkung des Botenstoffs Bradykinin, der beim erblichen Angioödem die Schwellungen verursacht. Icatibant ist ein synthetisches Peptid, das den Bradykinin-B2-Rezeptor selektiv und kompetitiv besetzt. Dadurch werden die durch Bradykinin ausgelöste Gefässerweiterung, die erhöhte Gefässdurchlässigkeit und die Schmerzen gehemmt, und die Schwellung bildet sich zurück.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Injektionsstelle (Schwellung, Rötung, Schmerz, Juckreiz, Brennen)"],"haeufig":["Kopfschmerzen","Schwindel","Übelkeit","Hautausschlag, Hautrötung, Juckreiz","Fieber","Erhöhte Leberwerte (Transaminasen)"],"unbekannt":["Nesselsucht (Urtikaria)"]},"schwangerschaft":"Keine ausreichenden Daten; nur anwenden, wenn der Nutzen das mögliche Risiko für das Ungeborene rechtfertigt (z. B. bei Kehlkopfschwellung).","stillzeit":"Nach einer Injektion 12 Stunden lang nicht stillen.","hinweise":["Nach Schulung kann die Fertigspritze selbst unter die Bauchhaut gespritzt werden; höchstens 3 Injektionen innerhalb von 24 Stunden.","Bei einer Kehlkopfattacke nach der Injektion sofort den Notfall aufsuchen.","Müdigkeit, Schwindel oder Kopfschmerzen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Injektionslösung in Fertigspritze (unter die Haut)"]},"idursulfase":{"wirkmechanismus":"Ersetzt ein fehlendes Enzym, damit sich Zuckerketten (Glykosaminoglykane) nicht mehr in Organen und Geweben anhäufen. Idursulfase ist eine in einer menschlichen Zelllinie hergestellte Iduronat-2-Sulfatase. Sie wird über Mannose-6-Phosphat-Rezeptoren in die Zellen aufgenommen und baut in den Lysosomen Dermatansulfat und Heparansulfat ab. Eine Wirkung auf die Beteiligung des Gehirns ist nicht belegt.","nebenwirkungen":{"sehrHaeufig":["Infusionsbedingte Reaktionen","Kopfschmerzen","Hautrötung mit Hitzegefühl (Flush)","Atemnot, pfeifende Atmung","Übelkeit, Erbrechen, Bauchschmerzen, Durchfall, Verdauungsbeschwerden","Nesselsucht, Ausschlag, Juckreiz, Hautrötung","Fieber, Brustschmerzen, Schwellung an der Infusionsstelle"],"haeufig":["Schwindel, Zittern","Herzrasen, Herzrhythmusstörungen, Blutdruckanstieg oder -abfall","Blauverfärbung der Haut (Zyanose), Sauerstoffmangel, Bronchospasmus (Verkrampfung der Atemwege), Husten","Zungenschwellung","Gelenkschmerzen","Schwellungen von Gesicht und Gliedern"],"unbekannt":["Anaphylaktische oder anaphylaktoide Reaktionen (schwere allergische Reaktionen)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen. Nur anwenden, wenn eindeutig nötig.","stillzeit":"Idursulfase geht bei Tieren in die Milch über. Entscheid über Stillen oder Behandlung nach ärztlicher Abwägung.","hinweise":["Wird wöchentlich als Infusion in eine Vene gegeben; nach mehreren problemlosen Infusionen im Spital ist eine Heiminfusion möglich.","Schwere allergische Reaktionen können auch nach Jahren und verzögert auftreten – Atemnot, Schwellungen oder Ausschlag sofort melden.","Bei Fieber oder Atemwegsinfekt vor der Infusion das Behandlungsteam informieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"iloprost":{"wirkmechanismus":"Erweitert Blutgefässe und hemmt das Verklumpen der Blutplättchen. Iloprost ist ein stabiles synthetisches Analogon von Prostacyclin und aktiviert Prostacyclin-(IP-)Rezeptoren; der Anstieg von cAMP entspannt die glatte Gefässmuskulatur. Inhaliert wirkt es vor allem auf die Lungengefässe und senkt den Lungengefässwiderstand; als Infusion verbessert es die Durchblutung kleiner Gefässe. Die Wirkung hält nur kurz an, deshalb wird mehrmals täglich inhaliert.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Gesichtsrötung (Flush)","Übelkeit","Kieferschmerzen","Husten (Inhalation)","Brustschmerzen, Engegefühl in der Brust","Blutungen, v. a. Nasenbluten","Periphere Ödeme (Wassereinlagerungen)"],"haeufig":["Schwindel","Blutdruckabfall","Synkope (Ohnmacht)","Herzrasen, Herzklopfen","Atemnot, Rachenreizung","Erbrechen, Durchfall","Hautausschlag","Rückenschmerzen"],"unbekannt":["Bronchospasmus (Verkrampfung der Atemwege)","Thrombozytopenie (Mangel an Blutplättchen)","Überempfindlichkeitsreaktionen","Geschmacksstörung"]},"schwangerschaft":"Infusion: in der Schwangerschaft kontraindiziert. Inhalation: nur bei klarer Notwendigkeit; Frauen im gebärfähigen Alter verhüten wirksam.","stillzeit":"Während der Behandlung nicht stillen (Infusion: kontraindiziert).","hinweise":["Inhalation nur mit dem dafür zugelassenen Vernebler; Lösung nicht mit Haut oder Augen in Kontakt bringen und nicht schlucken.","Wegen möglichem Blutdruckabfall langsam aufstehen; bei Schwindel kein Fahrzeug lenken.","Die Infusion erfolgt im Spital unter Kontrolle von Blutdruck und Puls."],"darreichung":["Lösung für einen Vernebler (Inhalation)","Konzentrat zur Herstellung einer Infusionslösung"]},"imatinib":{"wirkmechanismus":"Blockiert gezielt ein fehlgesteuertes Wachstumssignal in Krebszellen. Imatinib hemmt die Tyrosinkinase BCR-ABL, die durch das Philadelphia-Chromosom entsteht und die unkontrollierte Vermehrung der Leukämiezellen antreibt. Ausserdem hemmt es die Rezeptor-Tyrosinkinasen KIT (CD117) und PDGFR, die bei GIST bzw. bestimmten myeloproliferativen Erkrankungen dauerhaft aktiviert sind. Die betroffenen Zellen hören auf, sich zu teilen, und sterben ab.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Thrombozytopenie, Anämie","Kopfschmerzen","Übelkeit, Erbrechen, Durchfall, Dyspepsie (Verdauungsbeschwerden), Bauchschmerzen","Ödeme (Wassereinlagerungen), v. a. um die Augen, Gewichtszunahme","Hautausschlag, Dermatitis, Ekzem","Muskelkrämpfe, Muskel-, Knochen- und Gelenkschmerzen","Müdigkeit"],"haeufig":["Febrile Neutropenie, Panzytopenie","Appetitlosigkeit, Schlaflosigkeit","Schwindel, Kribbeln, Geschmacksstörungen","Lidschwellung, vermehrter Tränenfluss, Bindehautblutung, verschwommenes Sehen","Atemnot, Nasenbluten, Husten","Blähungen, Verstopfung, Reflux, Mundtrockenheit","Erhöhte Leberwerte","Juckreiz, trockene Haut, Haarausfall, nächtliches Schwitzen, Lichtempfindlichkeit"],"gelegentlich":["Herzschwäche, Lungenödem, Herzklopfen","Magen-Darm-Blutungen, Magengeschwür","Hepatitis, Gelbsucht","Pleuraerguss","Akutes Nierenversagen","Hypokaliämie, Hyponatriämie, Hypophosphatämie","Gürtelrose (Herpes zoster), Lungenentzündung, Sepsis","Subdurales Hämatom (Blutung unter der harten Hirnhaut)"],"selten":["Leberversagen, Lebernekrose","Herzrhythmusstörungen, Vorhofflimmern, Herzinfarkt, Perikarderguss","Hämolytische Anämie","Krampfanfälle, Sehnerventzündung","Darmverschluss, Kolitis","Angioödem","Lungenfibrose"],"unbekannt":["Hepatitis-B-Reaktivierung","Tumorlyse-Syndrom","Stevens-Johnson-Syndrom, DRESS (schwere Arzneimittelreaktion mit Hautausschlag)","Wachstumsverzögerung bei Kindern","Thrombose, Embolie","Anaphylaktischer Schock"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit anwenden (im Tierversuch fruchtschädigend, Fehlbildungsberichte beim Menschen). Frauen im gebärfähigen Alter müssen während der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung und mindestens 15 Tage nach der letzten Dosis nicht stillen.","hinweise":["Mit einer Mahlzeit und einem grossen Glas Wasser einnehmen (weniger Magenbeschwerden); Grapefruit meiden.","Regelmässig wiegen: rasche Gewichtszunahme oder Schwellungen melden (Flüssigkeitseinlagerung).","Blutbild und Leberwerte werden regelmässig kontrolliert; vor Beginn Test auf Hepatitis B.","Kann Schwindel und verschwommenes Sehen verursachen – Vorsicht beim Autofahren."],"darreichung":["Filmtabletten"]},"imiglucerase":{"wirkmechanismus":"Ersetzt ein Enzym, das bei Morbus Gaucher fehlt, sodass sich ein Fettstoff nicht mehr in den Zellen ablagert. Imiglucerase ist eine gentechnisch hergestellte saure beta-Glucosidase (Glucocerebrosidase), deren Zuckerketten auf Mannose enden. Darüber wird sie gezielt von Makrophagen (Fresszellen) aufgenommen und spaltet in deren Lysosomen das angehäufte Glucocerebrosid. So nehmen die Gaucher-Zellen in Milz, Leber und Knochenmark ab.","nebenwirkungen":{"haeufig":["Überempfindlichkeitsreaktionen: Atemnot, Husten, Nesselsucht, Angioödem (Schwellung), Juckreiz, Hautausschlag"],"gelegentlich":["Schwindel, Kopfschmerzen, Kribbeln (Parästhesien)","Herzrasen, Blauverfärbung der Haut (Zyanose), Hautrötung mit Hitzegefühl, Blutdruckabfall","Übelkeit, Erbrechen, Bauchkrämpfe, Durchfall","Gelenk- und Rückenschmerzen","Beschwerden an der Infusionsstelle (Brennen, Schwellung, steriler Abszess)","Fieber, Schüttelfrost, Müdigkeit, Brustbeschwerden"],"selten":["Anaphylaktoide Reaktionen (schwere allergische Reaktionen)"]},"schwangerschaft":"Begrenzte Erfahrungen (rund 150 Schwangerschaften) zeigen keinen Hinweis auf Schäden. Eine Fortführung ist nach ärztlicher Abwägung möglich, da die Krankheit in der Schwangerschaft aktiver werden kann.","stillzeit":"Keine Daten zum Übergang in die Muttermilch. Anwendung nach ärztlicher Abwägung.","hinweise":["Wird als Infusion in eine Vene gegeben, meist alle 2 Wochen; nach Schulung ist eine Heiminfusion möglich.","Während und nach der Infusion auf Zeichen einer allergischen Reaktion achten (Atemnot, Ausschlag, Schwindel) und sie sofort melden.","Blutbild, Organgrösse, Knochen und Antikörper werden regelmässig kontrolliert."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"imipenem-cilastatin":{"wirkmechanismus":"Tötet Bakterien ab, indem es den Aufbau ihrer Zellwand verhindert. Imipenem bindet an die Penicillin-bindenden Proteine und blockiert die Quervernetzung des Peptidoglykans; es ist gegen die meisten Betalaktamasen (auch ESBL) stabil und wirkt gegen grampositive, gramnegative (auch Pseudomonas) und anaerobe Erreger. Cilastatin hat selbst keine antibakterielle Wirkung: Es hemmt das Nierenenzym Dehydropeptidase-I, das Imipenem sonst abbauen würde, und sorgt so für wirksame Spiegel im Harn und schützt die Niere.","nebenwirkungen":{"haeufig":["Durchfall, Übelkeit, Erbrechen","Hautausschlag (Exanthem)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Erhöhte Leberwerte (Transaminasen, alkalische Phosphatase)","Venenentzündung (Thrombophlebitis) an der Infusionsstelle"],"gelegentlich":["Krampfanfälle, Muskelzuckungen (Myoklonien), Schwindel, Schläfrigkeit","Halluzinationen und Verwirrtheit","Blutbildveränderungen (Leukopenie, Neutropenie, Thrombozytopenie, Panzytopenie)","Blutdruckabfall","Nesselsucht, Juckreiz","Fieber","Erhöhtes Bilirubin"],"selten":["Agranulozytose (starker Mangel an weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Pseudomembranöse Kolitis (schwere Dickdarmentzündung)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, Erythema multiforme, Angioödem)","Hepatitis (Leberentzündung), Leberversagen","Akutes Nierenversagen","Hörverlust, Geschmacksstörungen, Verfärbung von Zähnen oder Zunge","Harmlose Rotfärbung des Urins"],"sehrSelten":["Hämolytische Anämie (Blutzerfall)","Verschlechterung einer Myasthenia gravis","Tinnitus (Ohrensausen), Drehschwindel","Herzrasen, Herzklopfen"],"unbekannt":["Unruhe (Agitiertheit)","Bewegungsstörungen (Dyskinesien)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen bei Schwangeren; in Tierversuchen an Affen traten Schäden auf. Anwendung nur, wenn der Nutzen das Risiko für das Kind klar überwiegt.","stillzeit":"Imipenem und Cilastatin gehen in kleinen Mengen in die Muttermilch über. Nur nach ärztlicher Abwägung anwenden.","hinweise":["Wird im Spital als Infusion gegeben; die Dosis richtet sich nach Infektion, Körpergewicht und Nierenfunktion.","Muskelzuckungen, Verwirrtheit oder Krampfanfälle sofort dem Behandlungsteam melden.","Unbedingt angeben, wenn Valproinsäure oder Ganciclovir eingenommen werden oder eine Antibiotika-Allergie besteht."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"immunglobulin-vom-menschen-normal":{"wirkmechanismus":"Liefert dem Körper fertige Abwehrstoffe (Antikörper) gegen zahlreiche Krankheitserreger. Das Präparat enthält überwiegend Immunglobulin G aus dem Plasma von Tausenden gesunden Spenderinnen und Spendern und ersetzt so fehlende Antikörper. In hoher Dosis wirkt es zudem immunmodulierend: Es blockiert Fc-Rezeptoren, neutralisiert schädliche Autoantikörper und dämpft Entzündungsreaktionen. Intravenös wirkt es sofort; subkutan gegeben entstehen gleichmässigere Spiegel.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (v. a. intravenös)","Subkutan: Reaktionen an der Infusionsstelle (Schwellung, Rötung, Juckreiz)"],"haeufig":["Fieber, Schüttelfrost, Müdigkeit","Übelkeit, Erbrechen","Muskel- und Gelenkschmerzen, Rückenschmerzen","Hautausschlag, Juckreiz","Blutdruckanstieg oder -abfall, Herzrasen","Blutarmut durch Hämolyse (v. a. hochdosiert intravenös)"],"gelegentlich":["Überempfindlichkeitsreaktionen","Aseptische Meningitis (nichtbakterielle Hirnhautentzündung)"],"unbekannt":["Anaphylaxie (allergischer Schock)","Thromboembolien (Herzinfarkt, Schlaganfall, Lungenembolie, Thrombose)","Akutes Nierenversagen","Transfusionsassoziierte akute Lungeninsuffizienz (TRALI)","Hämolytische Anämie"]},"schwangerschaft":"Langjährige Erfahrung zeigt keine schädlichen Wirkungen auf Schwangerschaft, Fötus oder Neugeborenes; Anwendung nach ärztlicher Abwägung. Immunglobuline gehen auf das Kind über.","stillzeit":"Immunglobuline gehen in die Muttermilch über; nachteilige Wirkungen für den Säugling sind nicht zu erwarten.","hinweise":["Vor und während der Infusion ausreichend trinken; erste Infusionen langsam und unter Überwachung.","Präparate sind nicht beliebig austauschbar; Name und Chargennummer werden dokumentiert.","Nach der Gabe können serologische Tests (z. B. Blutgruppen-Antikörper, Infektionsserologie) vorübergehend falsch positiv sein.","Bei Atemnot, Brustschmerzen, Beinschwellung, verminderter Urinmenge oder starken Kopfschmerzen sofort ärztliche Hilfe holen."],"darreichung":["Infusionslösung (intravenös)","Injektionslösung zur subkutanen Anwendung"]},"inclisiran":{"wirkmechanismus":"Senkt das LDL-Cholesterin, indem es die Leber daran hindert, das Protein PCSK9 herzustellen. Inclisiran ist eine doppelsträngige small interfering RNA (siRNA), die an N-Acetylgalactosamin gekoppelt ist und so gezielt über den Asialoglykoprotein-Rezeptor in die Leberzellen gelangt. Dort baut sie über den RNA-Interferenz-Mechanismus die Boten-RNA (mRNA) für PCSK9 ab. Weniger PCSK9 bedeutet mehr LDL-Rezeptoren auf den Leberzellen und damit ein um rund die Hälfte tieferes LDL-Cholesterin. Weil die Wirkung lange anhält, genügen nach zwei Startdosen Injektionen alle 6 Monate.","nebenwirkungen":{"haeufig":["Schmerzen an der Injektionsstelle","Rötung (Erythem) an der Injektionsstelle","Ausschlag an der Injektionsstelle"]},"schwangerschaft":"Vorsichtshalber vermeiden – keine ausreichenden Erfahrungen beim Menschen.","stillzeit":"Nicht bekannt, ob Inclisiran in die Muttermilch übergeht (bei Ratten nachgewiesen); ein Risiko für den Säugling ist nicht auszuschliessen – ärztlich abwägen.","hinweise":["Wird von einer Fachperson unter die Haut gespritzt, bevorzugt am Bauch (alternativ Oberarm oder Oberschenkel).","Termine einhalten; eine verpasste Injektion möglichst rasch nachholen und das weitere Schema ärztlich festlegen lassen.","Keine bekannten Wechselwirkungen mit anderen Medikamenten; Statin und Ernährungsmassnahmen weiterführen."],"darreichung":["Injektionslösung in Fertigspritze"]},"indacaterol-glycopyrronium":{"wirkmechanismus":"Hält die Bronchien bei COPD den ganzen Tag weiter offen. Indacaterol stimuliert als langwirksames Beta-2-Sympathomimetikum die Beta-2-Rezeptoren der Bronchialmuskulatur und entspannt sie über einen Anstieg von cAMP. Glycopyrronium blockiert langanhaltend die Muskarinrezeptoren (v. a. M3) und hemmt die bronchienverengende Wirkung von Acetylcholin. Die Wirkung setzt innerhalb von etwa 5 Minuten ein und hält 24 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Infekte der oberen Atemwege"],"haeufig":["Nasen-Rachen-Entzündung, Nasennebenhöhlenentzündung, Schnupfen","Harnwegsinfekte","Überempfindlichkeitsreaktionen","Kopfschmerzen, Schwindel","Husten, Hals- und Rachenschmerzen","Verdauungsbeschwerden (Dyspepsie)","Fieber, Brustschmerzen"],"gelegentlich":["Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Durchblutungsstörung des Herzens, Vorhofflimmern, Herzrasen, Herzklopfen","Glaukom (grüner Star)","Paradoxer Bronchospasmus, Nasenbluten","Mundtrockenheit","Juckreiz, Hautausschlag","Muskelkrämpfe, Muskelschmerzen","Schlaflosigkeit, Kribbeln (Parästhesien), Müdigkeit, Wassereinlagerungen"],"unbekannt":["Erhöhter Blutzucker","Harnverhalt","Heiserkeit (Dysphonie)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn der Nutzen das mögliche Risiko für das Kind überwiegt. Indacaterol kann die Wehentätigkeit hemmen.","stillzeit":"Nicht bekannt, ob die Wirkstoffe in die Muttermilch übergehen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Kapseln nur mit dem Breezhaler inhalieren, nie schlucken; die Kapsel erst kurz vor Gebrauch aus der Blisterpackung nehmen.","Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","Bei Augenschmerzen, verschwommenem Sehen oder Problemen beim Wasserlösen ärztlich abklären lassen."],"darreichung":["Hartkapseln mit Pulver zur Inhalation (Breezhaler)"]},"indapamid":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Ausscheidung von Salz und Wasser leicht steigert und die Blutgefässe entspannt. Indapamid hemmt im frühdistalen Tubulus der Niere die Rückresorption von Natrium und Chlorid (Natrium-Chlorid-Cotransporter), wodurch auch mehr Kalium und Magnesium ausgeschieden werden. In der niedrigen Dosis der Retardtablette (1,5 mg) steht die blutdrucksenkende Wirkung im Vordergrund, die harntreibende Wirkung ist gering. Zusätzlich vermindert es den Gefässwiderstand.","nebenwirkungen":{"haeufig":["Hypokaliämie (Kaliummangel)","Makulopapulöser Hautausschlag (Überempfindlichkeitsreaktion der Haut)"],"gelegentlich":["Hyponatriämie (Natriummangel)","Erbrechen","Purpura (punktförmige Hautblutungen)"],"selten":["Schwindel (Vertigo), Müdigkeit, Kopfschmerzen","Kribbeln (Parästhesien)","Übelkeit, Verstopfung, Mundtrockenheit","Hypochlorämie und Hypomagnesiämie (Chlorid- und Magnesiummangel)"],"sehrSelten":["Agranulozytose, Leukopenie, Thrombozytopenie, aplastische und hämolytische Anämie","Hyperkalzämie (erhöhtes Calcium)","Herzrhythmusstörungen, Blutdruckabfall","Pankreatitis (Bauchspeicheldrüsenentzündung), Leberfunktionsstörung","Angioödem, Nesselsucht, toxische epidermale Nekrolyse, Stevens-Johnson-Syndrom","Niereninsuffizienz"],"unbekannt":["QT-Verlängerung und Torsade de pointes (lebensbedrohliche Herzrhythmusstörung), Ohnmacht","Hepatische Enzephalopathie bei Leberinsuffizienz, Hepatitis","Photosensibilität (Lichtempfindlichkeit)","Verschlechterung eines Lupus erythematodes","Kurzsichtigkeit, verschwommenes Sehen, Aderhauterguss, akutes Engwinkelglaukom","Erhöhte Harnsäure, Blutzucker und Leberwerte"]},"schwangerschaft":"Nicht empfohlen: Diuretika können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes beeinträchtigen.","stillzeit":"Nicht anwenden: Indapamid geht in die Muttermilch über, kann die Milchbildung hemmen und beim Säugling Kaliummangel oder Überempfindlichkeitsreaktionen auslösen.","hinweise":["Retardtablette am Morgen unzerkaut mit Wasser schlucken.","Kalium, Natrium, Harnsäure und Blutzucker regelmässig kontrollieren lassen, besonders bei älteren Menschen und zu Behandlungsbeginn.","Bei plötzlicher Sehverschlechterung oder Augenschmerzen sofort ärztliche Hilfe suchen.","Sportlerinnen und Sportler: Indapamid steht als Diuretikum auf der Dopingliste."],"darreichung":["Retardtabletten"]},"infliximab":{"wirkmechanismus":"Bremst Entzündungen im Darm, in Gelenken und in der Haut, indem es einen zentralen Entzündungsbotenstoff ausschaltet. Infliximab ist ein chimärer (Maus-Mensch-)monoklonaler IgG1-Antikörper, der lösliches und membrangebundenes TNF-alpha mit hoher Affinität bindet. Dadurch wird die TNF-vermittelte Entzündungskaskade unterbrochen, und TNF-produzierende Immunzellen werden teilweise abgebaut. Zugleich wird die Abwehr gegen Infektionen, besonders Tuberkulose, geschwächt.","nebenwirkungen":{"sehrHaeufig":["Virusinfektionen (z. B. Grippe, Herpes)","Infektionen der oberen Atemwege, Nasennebenhöhlenentzündung","Kopfschmerzen","Bauchschmerzen, Übelkeit","Infusionsreaktionen (Fieber, Schüttelfrost, Juckreiz, Atemnot während oder kurz nach der Infusion)"],"haeufig":["Bakterielle Infektionen (z. B. Sepsis, Abszesse, Zellulitis)","Neutropenie, Leukopenie, Anämie","Depression, Schlaflosigkeit, Schwindel","Herzrasen, Blutdruckveränderungen, Hitzewallungen","Durchfall, Verstopfung, Verdauungsbeschwerden","Erhöhte Leberwerte","Neue oder verschlechterte Psoriasis, Ausschlag, Nesselsucht","Gelenk- und Muskelschmerzen, Brustschmerzen, Müdigkeit, Fieber"],"gelegentlich":["Tuberkulose, Pilzinfektionen","Thrombozytopenie (Mangel an Blutplättchen)","Anaphylaxie (schwere allergische Reaktion)","Lupus-ähnliches Syndrom","Verschlechterung einer Herzinsuffizienz, Herzrhythmusstörungen","Interstitielle Lungenerkrankung, Lungenödem","Hepatitis (Leberentzündung)","Krampfanfälle, Neuropathie (Nervenschädigung)"],"selten":["Lymphom","Demyelinisierende Erkrankungen (z. B. Multiple Sklerose, Sehnerventzündung, Guillain-Barré-Syndrom)","Autoimmune Hepatitis","Vaskulitis (Gefässentzündung)","Toxische epidermale Nekrolyse, Stevens-Johnson-Syndrom","Agranulozytose (fast völliges Fehlen bestimmter weisser Blutkörperchen)"],"unbekannt":["Hepatosplenisches T-Zell-Lymphom","Leberversagen, Hepatitis-B-Reaktivierung","Melanom, Merkelzellkarzinom","Herzinfarkt oder Durchblutungsstörung des Herzens sowie vorübergehender Sehverlust während oder kurz nach der Infusion"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Infliximab passiert die Plazenta und ist bis zu 12 Monate nach der Geburt im Blut des Kindes nachweisbar; in dieser Zeit keine Lebendimpfungen beim Säugling.","stillzeit":"Geht in sehr geringen Mengen in die Muttermilch über; Stillen ist nach ärztlicher Abwägung möglich. Lebendimpfungen des gestillten Säuglings ärztlich besprechen.","hinweise":["Vor Beginn auf Tuberkulose und Hepatitis B testen und den Impfstatus vervollständigen lassen.","Infusionen erfolgen unter Überwachung; Fieber, Atemnot oder Ausschlag auch Tage nach der Infusion melden.","Bei Infektzeichen (Fieber, Husten, Brennen beim Wasserlassen) rasch ärztlich abklären lassen.","Regelmässige Hautkontrollen und Sonnenschutz (Hautkrebsrisiko)."],"darreichung":["Pulver für ein Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung zur subkutanen Anwendung (Fertigpen, Fertigspritze)"]},"influenza-impfstoff-inaktiviert":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen die in der kommenden Saison erwarteten Grippeviren zu bilden. Der Impfstoff enthält abgetötete, gespaltene Viren oder gereinigte Oberflächenproteine (Hämagglutinin, Neuraminidase) von Influenza-A- und -B-Stämmen; die Zusammensetzung wird jedes Jahr nach Empfehlung der WHO angepasst. Antikörper gegen das Hämagglutinin verhindern, dass die Viren in die Zellen eindringen. Der Schutz beginnt etwa 2 Wochen nach der Impfung und hält etwa eine Saison an; der Hochdosis-Impfstoff enthält die vierfache Antigenmenge für eine stärkere Antwort im Alter.","nebenwirkungen":{"sehrHaeufig":["Schmerzen an der Einstichstelle","Kopfschmerzen","Muskelschmerzen","Unwohlsein, Müdigkeit"],"haeufig":["Rötung, Schwellung und Verhärtung an der Einstichstelle","Fieber, Schüttelfrost","Gelenkschmerzen","Schwitzen"],"gelegentlich":["Schwindel","Übelkeit, Durchfall","Bluterguss, Juckreiz und Wärmegefühl an der Einstichstelle"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Juckreiz)","Lymphknotenschwellung","Kribbeln (Parästhesien)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Vorübergehende Thrombozytopenie (Mangel an Blutplättchen)","Guillain-Barré-Syndrom (Nervenentzündung mit Lähmungen) und andere Nervenentzündungen","Vaskulitis (Gefässentzündung)","Fieberkrämpfe"]},"schwangerschaft":"Kann in jedem Schwangerschaftsdrittel gegeben werden und wird Schwangeren in der Schweiz empfohlen; die Impfung schützt auch das Neugeborene in den ersten Lebensmonaten.","stillzeit":"Impfung während der Stillzeit möglich.","hinweise":["Jährlich impfen, idealerweise zwischen Mitte Oktober und Beginn der Grippewelle, da sich die Viren laufend verändern.","Der Schutz beginnt nach etwa 2 Wochen; die Impfung schützt nicht vor Erkältungen durch andere Viren.","Kinder unter 9 Jahren, die zum ersten Mal gegen Grippe geimpft werden, erhalten 2 Dosen im Abstand von 4 Wochen."],"darreichung":["Injektionssuspension in Fertigspritze"]},"insulin-aspart":{"wirkmechanismus":"Dämpft den Blutzuckeranstieg nach dem Essen und wirkt schneller und kürzer als Humaninsulin. Bei Insulin aspart ist die Aminosäure Prolin an Position B28 durch Asparaginsäure ersetzt; dadurch bilden sich im Unterhautgewebe weniger Insulin-Komplexe und das Insulin gelangt schneller ins Blut. Die Wirkung beginnt nach 10–20 Minuten, ist nach 1–3 Stunden am stärksten und hält 3–5 Stunden an; am Insulinrezeptor wirkt es wie Humaninsulin. Fiasp enthält zusätzlich Nicotinamid (Vitamin B3), das die Aufnahme weiter beschleunigt. NovoMix 30 enthält 30 % gelöstes und 70 % an Protamin gebundenes, verzögert wirkendes Insulin aspart.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit"],"haeufig":["Reaktionen an der Injektions- oder Infusionsstelle (Rötung, Schwellung, Juckreiz, Bluterguss; unter Fiasp häufig, unter NovoRapid gelegentlich)","Allergische Hautreaktionen wie Ausschlag, Juckreiz, Nesselsucht, Ekzem (unter Fiasp häufig, unter NovoRapid gelegentlich)"],"gelegentlich":["Lipodystrophie (Verdickung oder Schwund des Unterhautfettgewebes an der Spritzstelle)","Refraktionsanomalien (vorübergehende Sehstörungen zu Behandlungsbeginn)","Diabetische Retinopathie (vorübergehende Verschlechterung bei rascher Blutzuckersenkung)","Ödeme (Wassereinlagerungen), vor allem zu Behandlungsbeginn"],"selten":["Periphere Neuropathie (akute, schmerzhafte Nervenbeschwerden bei rascher Blutzuckersenkung)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)"]},"schwangerschaft":"Erlaubt: Studien bei Schwangeren mit Diabetes zeigten keine Nachteile für Mutter oder Kind; Insulin ist das Mittel der Wahl. Der Insulinbedarf ändert sich im Verlauf und nach der Geburt – engmaschige Blutzuckerkontrollen.","stillzeit":"Erlaubt; für das gestillte Kind besteht kein Risiko. Die Insulindosis muss eventuell angepasst werden.","hinweise":["NovoRapid unmittelbar vor der Mahlzeit spritzen (bei Bedarf kurz danach); Fiasp 0–2 Minuten vor Beginn oder bis 20 Minuten nach Beginn der Mahlzeit.","NovoMix 30 vor jeder Injektion durch Rollen und Schwenken gleichmässig mischen; Mischinsulin nicht intravenös und nicht in Pumpen verwenden.","Die Spritzstelle innerhalb einer Körperregion regelmässig wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen."],"darreichung":["Injektionslösung","Injektionssuspension (Mischinsulin)","Fertigpen","Patrone","Durchstechflasche","Patrone für Insulinpumpen"]},"insulin-degludec":{"wirkmechanismus":"Deckt als Basalinsulin gleichmässig den Grundbedarf des Körpers an Insulin. Insulin degludec bildet nach der Injektion unter die Haut lange, lösliche Ketten aus Insulin-Hexameren, aus denen einzelne Insulinmoleküle langsam und stetig ins Blut gelangen; über eine Fettsäure-Seitenkette bindet es zusätzlich an Albumin. Die Halbwertszeit beträgt rund 25 Stunden, die Wirkung hält über 42 Stunden an und ist von Tag zu Tag sehr gleichmässig. Am Insulinrezeptor wirkt es wie Humaninsulin: mehr Zuckeraufnahme in die Zellen, weniger Zuckerneubildung in der Leber.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit"],"haeufig":["Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz, Bluterguss)"],"gelegentlich":["Lipodystrophie (Verdickung oder Schwund des Unterhautfettgewebes an der Spritzstelle)","Periphere Ödeme (Wassereinlagerungen in Armen und Beinen)"],"selten":["Überempfindlichkeitsreaktionen (z. B. Schwellung von Zunge oder Lippen, Juckreiz, Durchfall, Übelkeit, Müdigkeit), im Extremfall Anaphylaxie","Urtikaria (Nesselsucht)"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)"]},"schwangerschaft":"Kann bei Bedarf angewendet werden: Eine Studie bei Schwangeren mit Typ-1-Diabetes zeigte keine Nachteile für Mutter oder Kind. Engmaschige Blutzuckerkontrollen, da sich der Insulinbedarf im Verlauf und nach der Geburt ändert.","stillzeit":"Erlaubt; Auswirkungen auf das gestillte Kind sind nicht zu erwarten. Die Insulindosis muss eventuell angepasst werden.","hinweise":["Einmal täglich spritzen, möglichst zur gleichen Tageszeit; falls nötig ist eine andere Tageszeit möglich, solange zwischen zwei Injektionen mindestens 8 Stunden liegen.","Die Dosisanzeige des Pens zeigt immer Einheiten, auch beim Pen mit 200 Einheiten/ml; Insulin nie mit einer Spritze aus dem Pen aufziehen.","Die Spritzstelle innerhalb einer Körperregion regelmässig wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen."],"darreichung":["Injektionslösung 100 und 200 Einheiten/ml","Fertigpen","Patrone"]},"insulin-degludec-insulin-aspart":{"wirkmechanismus":"Senkt den Blutzucker, indem es die Wirkung des körpereigenen Insulins ersetzt: Zucker wird vermehrt in Muskel- und Fettzellen aufgenommen und die Zuckerbildung in der Leber gehemmt. Insulin degludec bildet unter der Haut lange Ketten (Multihexamere), aus denen es langsam und gleichmässig freigesetzt wird; die Wirkung hält über 24 Stunden an (Basalinsulin). Insulin aspart wird dagegen rasch aufgenommen und deckt den Insulinbedarf zur Mahlzeit.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)"],"haeufig":["Reaktionen an der Einstichstelle (Rötung, Schwellung, Juckreiz, Bluterguss)"],"gelegentlich":["Lipodystrophie (Veränderungen des Unterhautfettgewebes an der Einstichstelle)","Periphere Ödeme (Wassereinlagerungen)"],"unbekannt":["Überempfindlichkeitsreaktionen und Nesselsucht, bis zur Anaphylaxie (schwere allergische Reaktion)","Kutane Amyloidose (Knoten unter der Haut an der Einstichstelle)"]},"schwangerschaft":"Begrenzte Erfahrungen. Anwendung nach ärztlicher Abwägung möglich; da sich der Insulinbedarf in der Schwangerschaft ändert, sind engmaschige Blutzuckerkontrollen nötig.","stillzeit":"Keine Erfahrungen, nachteilige Wirkungen auf den gestillten Säugling sind aber nicht zu erwarten; die Dosis muss eventuell angepasst werden.","hinweise":["Ein- oder zweimal täglich zu einer Hauptmahlzeit unter die Haut spritzen; nie in eine Vene und nicht in Insulinpumpen.","Anzeichen einer Unterzuckerung kennen und stets Traubenzucker mitführen; Blutzucker regelmässig messen.","Unterzuckerungen beeinträchtigen Konzentration und Fahrtüchtigkeit – vor dem Autofahren Blutzucker prüfen.","Einstichstelle innerhalb der Körperregion bei jeder Injektion wechseln."],"darreichung":["Injektionslösung im Fertigpen"]},"insulin-degludec-liraglutid":{"wirkmechanismus":"Kombiniert zwei blutzuckersenkende Wirkprinzipien. Insulin degludec ist ein ultralang wirkendes Basalinsulin, das aus einem Depot unter der Haut gleichmässig über mehr als 24 Stunden freigesetzt wird. Liraglutid ahmt das Darmhormon GLP-1 nach: Es steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung, verlangsamt die Magenentleerung und dämpft den Appetit. Dadurch sinkt der Blutzucker mit weniger Gewichtszunahme als unter Insulin allein.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)"],"haeufig":["Übelkeit","Durchfall","Erbrechen","Verstopfung","Verdauungsbeschwerden, Bauchschmerzen, Blähungen","Verminderter Appetit","Reaktionen an der Einstichstelle","Erhöhte Lipase- und Amylasewerte im Blut"],"gelegentlich":["Nesselsucht, Überempfindlichkeitsreaktionen","Dehydratation (Flüssigkeitsmangel)","Aufstossen","Geschmacksstörung","Gallensteine, Gallenblasenentzündung","Erhöhter Puls"],"unbekannt":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Anaphylaxie (schwere allergische Reaktion)","Lipodystrophie und kutane Amyloidose an der Einstichstelle","Periphere Ödeme (Wassereinlagerungen)"]},"schwangerschaft":"Nicht empfohlen. Bei Kinderwunsch oder Eintritt einer Schwangerschaft absetzen und auf Insulin umstellen.","stillzeit":"Mangels Erfahrungen während der Stillzeit nicht anwenden.","hinweise":["Einmal täglich, möglichst immer zur gleichen Tageszeit, unabhängig von den Mahlzeiten unter die Haut spritzen; die Dosis wird in Dosisschritten angegeben (höchstens 50 pro Tag).","Nicht zusammen mit anderen GLP-1-Agonisten anwenden.","Anzeichen einer Unterzuckerung kennen und stets Traubenzucker mitführen; vor dem Autofahren Blutzucker prüfen.","Übelkeit tritt vor allem zu Beginn auf; auf ausreichendes Trinken achten und anhaltende starke Bauchschmerzen sofort ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen"]},"insulin-detemir":{"wirkmechanismus":"Deckt den Grundbedarf an Insulin (Basalinsulin) und senkt so den Blutzucker. Insulin detemir trägt eine angehängte Fettsäure (Myristinsäure): Dadurch lagern sich die Moleküle an der Einstichstelle zusammen und binden im Blut an Albumin, was Aufnahme und Wirkung über bis zu 24 Stunden verlangsamt. Am Insulinrezeptor fördert es die Zuckeraufnahme in Muskel- und Fettgewebe und hemmt die Zuckerbildung in der Leber.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)"],"haeufig":["Reaktionen an der Einstichstelle (Rötung, Schwellung, Juckreiz, Schmerz)"],"gelegentlich":["Allergische Reaktionen (Nesselsucht, Hautausschlag)","Lipodystrophie (Veränderungen des Unterhautfettgewebes an der Einstichstelle)","Ödeme (Wassereinlagerungen) zu Behandlungsbeginn","Vorübergehende Sehstörungen (Refraktionsanomalien)","Vorübergehende Verschlechterung einer diabetischen Retinopathie"],"selten":["Schmerzhafte Nervenstörung (periphere Neuropathie) bei rascher Verbesserung der Blutzuckerwerte"],"sehrSelten":["Anaphylaktische Reaktionen (schwere allergische Reaktion)"],"unbekannt":["Kutane Amyloidose (Knoten unter der Haut an der Einstichstelle)"]},"schwangerschaft":"Kann angewendet werden, wenn klinisch erforderlich; da sich der Insulinbedarf in der Schwangerschaft ändert, sind engmaschige Blutzuckerkontrollen nötig.","stillzeit":"Kann angewendet werden; Insulindosis und Ernährung müssen eventuell angepasst werden.","hinweise":["Ein- oder zweimal täglich, jeweils etwa zur gleichen Tageszeit, unter die Haut spritzen; nie in eine Vene und nicht in Insulinpumpen.","Anzeichen einer Unterzuckerung kennen und stets Traubenzucker mitführen; Blutzucker regelmässig messen.","Unterzuckerungen beeinträchtigen Konzentration und Fahrtüchtigkeit – vor dem Autofahren Blutzucker prüfen.","Einstichstelle innerhalb der Körperregion bei jeder Injektion wechseln."],"darreichung":["Injektionslösung im Fertigpen","Injektionslösung in Patronen"]},"insulin-glargin":{"wirkmechanismus":"Deckt als Basalinsulin gleichmässig den Grundbedarf des Körpers an Insulin, unabhängig von den Mahlzeiten. Insulin glargin ist im leicht sauren Lösungsmittel gelöst und fällt nach der Injektion unter die Haut im neutralen Gewebe als feine Ablagerung aus, aus der es langsam und gleichmässig freigesetzt wird. Dadurch wirkt es ohne ausgeprägten Wirkgipfel rund 24 Stunden (Toujeo mit 300 Einheiten/ml noch etwas flacher und länger). Im Körper wird es zum aktiven Metaboliten M1 umgewandelt, der am Insulinrezeptor wie Humaninsulin wirkt: mehr Zuckeraufnahme in die Zellen, weniger Zuckerneubildung in der Leber.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit, oft auch nachts"],"haeufig":["Lipohypertrophie (Verdickung des Unterhautfettgewebes an der Spritzstelle)","Reaktionen an der Injektionsstelle (Rötung, Schmerz, Juckreiz, Nesselsucht, Schwellung)"],"gelegentlich":["Lipoatrophie (Schwund des Unterhautfettgewebes an der Spritzstelle)"],"selten":["Allergische Sofortreaktionen (Hautreaktionen am ganzen Körper, Angioödem, Bronchospasmus, Blutdruckabfall, Schock)","Vorübergehende Sehstörungen","Retinopathie (vorübergehende Verschlechterung der diabetischen Netzhauterkrankung bei rascher Blutzuckersenkung)","Ödeme (Wassereinlagerungen)"],"sehrSelten":["Dysgeusie (Geschmacksstörung)","Myalgie (Muskelschmerzen)"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)"]},"schwangerschaft":"Kann bei Bedarf angewendet werden: Daten von über 1000 Schwangerschaften zeigen keine schädliche Wirkung auf Schwangerschaft oder Kind. Engmaschige Blutzuckerkontrollen, da sich der Insulinbedarf im Verlauf und nach der Geburt ändert.","stillzeit":"Erlaubt; Insulin wird vom gestillten Kind nicht über den Darm aufgenommen. Die Insulindosis und die Ernährung müssen eventuell angepasst werden.","hinweise":["Einmal täglich, möglichst immer zur gleichen Tageszeit spritzen; nicht mit anderen Insulinen mischen oder verdünnen.","Toujeo (300 Einheiten/ml) nie mit einer Spritze aus dem Pen aufziehen – Gefahr schwerer Überdosierung.","Die Spritzstelle innerhalb einer Körperregion regelmässig wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen."],"darreichung":["Injektionslösung 100 Einheiten/ml (Lantus, Abasaglar)","Injektionslösung 300 Einheiten/ml (Toujeo)","Fertigpen","Patrone","Durchstechflasche"]},"insulin-glargin-lixisenatid":{"wirkmechanismus":"Kombiniert zwei blutzuckersenkende Wirkprinzipien. Insulin glargin ist ein lang wirkendes Insulin, das unter der Haut feine Kristalle bildet und gleichmässig über etwa 24 Stunden freigesetzt wird; es senkt vor allem den Nüchternblutzucker. Lixisenatid ahmt das Darmhormon GLP-1 nach: Es steigert blutzuckerabhängig die Insulinausschüttung, hemmt die Glukagonfreisetzung und verlangsamt die Magenentleerung, was besonders den Blutzuckeranstieg nach der Mahlzeit dämpft.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)"],"haeufig":["Übelkeit","Durchfall","Erbrechen","Schwindel"],"gelegentlich":["Kopfschmerzen","Verdauungsbeschwerden, Bauchschmerzen","Müdigkeit","Nesselsucht (Urtikaria)","Nasen-Rachen-Entzündung, Infekte der oberen Atemwege"],"unbekannt":["Reaktionen an der Einstichstelle","Lipodystrophie und kutane Amyloidose an der Einstichstelle","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nicht empfohlen. Bei Kinderwunsch oder Eintritt einer Schwangerschaft absetzen und auf Insulin umstellen.","stillzeit":"Während der Stillzeit nicht anwenden.","hinweise":["Einmal täglich innerhalb einer Stunde vor einer Mahlzeit spritzen, möglichst jeden Tag vor derselben Mahlzeit.","Übelkeit tritt vor allem zu Beginn auf und lässt meist nach; auf ausreichendes Trinken achten.","Anzeichen einer Unterzuckerung kennen und stets Traubenzucker mitführen; vor dem Autofahren Blutzucker prüfen.","Einstichstelle bei jeder Injektion wechseln."],"darreichung":["Injektionslösung im Fertigpen"]},"insulin-glulisin":{"wirkmechanismus":"Dämpft den Blutzuckeranstieg nach dem Essen und wirkt schneller und kürzer als Humaninsulin. Bei Insulin glulisin ist Asparagin an Position B3 durch Lysin und Lysin an Position B29 durch Glutaminsäure ersetzt; dadurch wird es nach der Injektion unter die Haut rascher aufgenommen. Die Wirkung beginnt nach etwa 10–20 Minuten; am Insulinrezeptor wirkt es wie Humaninsulin, steigert die Zuckeraufnahme in Muskel- und Fettgewebe und hemmt die Zuckerneubildung in der Leber. Es wird kurz vor oder unmittelbar nach einer Mahlzeit gespritzt und meist mit einem lang wirkenden Insulin kombiniert.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit"],"haeufig":["Reaktionen an der Injektionsstelle und lokale Überempfindlichkeitsreaktionen (Rötung, Schwellung, Juckreiz)"],"gelegentlich":["Systemische Überempfindlichkeitsreaktionen (Ausschlag am ganzen Körper, Nesselsucht, Atemnot, Blutdruckabfall), im Extremfall Anaphylaxie"],"selten":["Lipodystrophie (Verdickung oder Schwund des Unterhautfettgewebes an der Spritzstelle)"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)"]},"schwangerschaft":"Nur nach ärztlicher Abwägung: Die Erfahrungen bei Schwangeren sind begrenzt, Tierstudien zeigen keine schädliche Wirkung. Engmaschige Blutzuckerkontrollen, da sich der Insulinbedarf im Verlauf und nach der Geburt ändert.","stillzeit":"Vertretbar; Insulin wird vom gestillten Kind nicht über den Darm aufgenommen. Die Insulindosis und die Ernährung müssen eventuell angepasst werden.","hinweise":["0–15 Minuten vor oder unmittelbar nach einer Mahlzeit spritzen.","Darf in der Spritze nur mit NPH-Humaninsulin gemischt werden, nicht mit anderen Insulinen.","Die Spritzstelle innerhalb einer Körperregion regelmässig wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen."],"darreichung":["Injektionslösung","Fertigpen","Patrone","Durchstechflasche"]},"insulin-human":{"wirkmechanismus":"Senkt den Blutzucker, indem es wie das körpereigene Hormon die Aufnahme von Zucker aus dem Blut in Muskel- und Fettzellen fördert. Humaninsulin wird gentechnisch hergestellt und ist mit menschlichem Insulin identisch; es bindet an den Insulinrezeptor, steigert Glukoseaufnahme und -speicherung und hemmt die Zuckerneubildung in der Leber sowie den Fettabbau. Normalinsulin (Altinsulin) wirkt nach etwa 30 Minuten, am stärksten nach 1,5–3,5 Stunden und rund 8 Stunden lang; es wird deshalb etwa 30 Minuten vor dem Essen gespritzt und kann im Spital auch intravenös gegeben werden. NPH-Insulin ist an Protamin gebunden und wirkt verzögert bis etwa 24 Stunden; Mischinsuline enthalten beide Anteile.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit"],"gelegentlich":["Allergische Hautreaktionen (Nesselsucht, Ausschlag)","Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz)","Lipodystrophie (Verdickung oder Schwund des Unterhautfettgewebes an der Spritzstelle)","Ödeme (Wassereinlagerungen), vor allem zu Behandlungsbeginn","Diabetische Retinopathie (vorübergehende Verschlechterung der Netzhauterkrankung bei rascher Blutzuckersenkung)"],"selten":["Periphere Neuropathie (akute, schmerzhafte Nervenbeschwerden bei rascher Blutzuckersenkung)"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Refraktionsanomalien (vorübergehende Sehstörungen zu Behandlungsbeginn)"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)"]},"schwangerschaft":"Erlaubt: Insulin ist das Mittel der Wahl bei Diabetes in der Schwangerschaft. Der Insulinbedarf sinkt meist im ersten Drittel, steigt im zweiten und dritten und fällt nach der Geburt rasch ab – engmaschige Blutzuckerkontrollen nötig.","stillzeit":"Erlaubt; für das gestillte Kind besteht kein Risiko. Die Insulindosis und die Ernährung müssen eventuell angepasst werden.","hinweise":["Die Spritzstelle innerhalb einer Körperregion bei jeder Injektion wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","NPH- und Mischinsulin vor der Injektion durch Rollen und Schwenken gleichmässig milchig-trüb mischen; sie dürfen nicht intravenös und nicht in Insulinpumpen verwendet werden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen.","Unangebrochene Pens und Patronen im Kühlschrank (nicht einfrieren) lagern, angebrochene bei Raumtemperatur nur während der in der Packungsbeilage genannten Frist verwenden; Pens nie mit anderen Personen teilen."],"darreichung":["Injektionslösung (Normalinsulin)","Injektionssuspension (NPH- und Mischinsulin)","Fertigpen","Patrone","Durchstechflasche"]},"insulin-icodec":{"wirkmechanismus":"Deckt den Grundbedarf an Insulin (Basalinsulin) über eine ganze Woche und senkt so den Blutzucker. Insulin icodec trägt eine Fettsäure-Seitenkette, über die es sehr stark und umkehrbar an Albumin im Blut bindet; zudem bindet es schwächer an den Insulinrezeptor und wird dadurch langsamer abgebaut. So entsteht ein Speicher, aus dem gleichmässig wirksames Insulin freigesetzt wird (Halbwertszeit etwa eine Woche). Am Insulinrezeptor fördert es die Zuckeraufnahme in Muskel- und Fettzellen und hemmt die Zuckerbildung in der Leber.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung)"],"haeufig":["Reaktionen an der Einstichstelle (Rötung, Schwellung, Juckreiz, Bluterguss)"],"unbekannt":["Überempfindlichkeitsreaktionen","Periphere Ödeme (Wassereinlagerungen)","Lipodystrophie (Veränderungen des Unterhautfettgewebes an der Einstichstelle)","Kutane Amyloidose (Knoten unter der Haut an der Einstichstelle)"]},"schwangerschaft":"Keine Erfahrungen; aus Vorsicht möglichst nicht anwenden. Bei Kinderwunsch oder Schwangerschaft das weitere Vorgehen (z. B. Wechsel auf ein täglich gespritztes Insulin) ärztlich besprechen.","stillzeit":"Nicht bekannt, ob Insulin icodec in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Einmal pro Woche, immer am gleichen Wochentag, unter die Haut spritzen.","Eine vergessene Dosis so bald wie möglich nachholen; das weitere Vorgehen gemäss ärztlicher Anweisung bzw. Packungsbeilage.","Anzeichen einer Unterzuckerung kennen und stets Traubenzucker mitführen; vor dem Autofahren Blutzucker prüfen.","Die Umstellung von einem täglichen Basalinsulin erfolgt nach ärztlichem Schema; Blutzucker in dieser Zeit häufiger messen."],"darreichung":["Injektionslösung im Fertigpen"]},"insulin-lispro":{"wirkmechanismus":"Dämpft den Blutzuckeranstieg nach dem Essen und wirkt schneller und kürzer als Humaninsulin. Bei Insulin lispro sind die Aminosäuren Prolin und Lysin an den Positionen B28 und B29 vertauscht; die Moleküle lagern sich im Unterhautgewebe weniger zusammen und gelangen rascher ins Blut. Die Wirkung setzt nach etwa 15 Minuten ein und hält rund 2–5 Stunden an; am Insulinrezeptor wirkt es wie Humaninsulin (mehr Zuckeraufnahme in die Zellen, weniger Zuckerneubildung in der Leber). Lyumjev enthält zusätzlich Treprostinil und Citrat, die die Aufnahme nochmals beschleunigen. In Humalog Mix ist ein Teil an Protamin gebunden und wirkt verzögert.","nebenwirkungen":{"sehrHaeufig":["Hypoglykämie (Unterzuckerung) mit Zittern, Schwitzen, Herzklopfen, Heisshunger oder Verwirrtheit; schwer bis zur Bewusstlosigkeit"],"haeufig":["Lokale allergische Reaktionen und Reaktionen an der Injektionsstelle (Rötung, Schwellung, Juckreiz)"],"gelegentlich":["Lipodystrophie (Verdickung oder Schwund des Unterhautfettgewebes an der Spritzstelle)"],"selten":["Generalisierte allergische Reaktionen (Ausschlag am ganzen Körper, Atemnot, Blutdruckabfall, Herzrasen, Schwitzen), im Extremfall Anaphylaxie"],"unbekannt":["Kutane Amyloidose (knotige Ablagerungen unter der Haut an häufig benutzten Spritzstellen, mit verschlechterter Insulinaufnahme)","Ödeme (Wassereinlagerungen), vor allem bei rascher Verbesserung der Blutzuckereinstellung"]},"schwangerschaft":"Erlaubt: Umfangreiche Erfahrungen zeigen keine schädliche Wirkung auf Schwangerschaft oder Kind; Insulin ist das Mittel der Wahl bei Diabetes in der Schwangerschaft. Der Insulinbedarf ändert sich im Verlauf und nach der Geburt – engmaschige Blutzuckerkontrollen.","stillzeit":"Erlaubt; für das gestillte Kind besteht kein Risiko. Die Insulindosis und die Ernährung müssen eventuell angepasst werden.","hinweise":["Kurz vor der Mahlzeit spritzen (Humalog 0–15 Minuten vorher; Lyumjev zu Beginn oder bis 20 Minuten nach Beginn der Mahlzeit).","Insulin aus Pens mit 200 Einheiten/ml nie mit einer Spritze aufziehen – Gefahr schwerer Überdosierung.","Die Spritzstelle innerhalb einer Körperregion regelmässig wechseln, um Verhärtungen und Ablagerungen im Unterhautgewebe zu vermeiden.","Immer Traubenzucker bei sich tragen; eine Unterzuckerung beeinträchtigt die Fahrtüchtigkeit – vor dem Autofahren Blutzucker messen."],"darreichung":["Injektionslösung (100 und 200 Einheiten/ml)","Injektionssuspension (Mischinsulin)","Fertigpen","Patrone","Durchstechflasche"]},"interferon-beta-1a":{"wirkmechanismus":"Dämpft fehlgeleitete Entzündungsreaktionen des Immunsystems gegen das Nervensystem. Interferon beta-1a ist ein gentechnisch hergestelltes körpereigenes Botenstoff-Eiweiss, das an Interferon-Rezeptoren auf Immunzellen bindet. Es vermindert die Aktivierung entzündungsfördernder T-Zellen, fördert entzündungshemmende Botenstoffe und erschwert den Übertritt von Immunzellen über die Blut-Hirn-Schranke. Dadurch werden Schübe seltener und die Behinderungszunahme verlangsamt.","nebenwirkungen":{"sehrHaeufig":["Grippeähnliche Beschwerden (Fieber, Schüttelfrost, Muskelschmerzen, Müdigkeit), v. a. zu Beginn","Kopfschmerzen","Reaktionen an der Einstichstelle (Rötung, Schmerzen, Schwellung)","Verminderte weisse Blutkörperchen (Lymphopenie, Neutropenie, Leukopenie)","Leichter Anstieg der Leberwerte ohne Beschwerden"],"haeufig":["Depression","Schlaflosigkeit","Übelkeit, Erbrechen, Durchfall","Juckreiz, Hautausschlag, Haarausfall","Muskel- und Gelenkschmerzen, Muskelsteifigkeit","Anämie (Blutarmut)","Nekrose (Gewebeschaden) an der Einstichstelle"],"gelegentlich":["Krampfanfälle","Hepatitis (Leberentzündung)","Thrombozytopenie (Mangel an Blutplättchen)","Schilddrüsenüber- oder -unterfunktion","Nesselsucht"],"selten":["Suizidversuch","Leberversagen","Anaphylaxie (schwere allergische Reaktion), Angioödem","Stevens-Johnson-Syndrom und andere schwere Hautreaktionen","Thrombotische Mikroangiopathie und hämolytisch-urämisches Syndrom","Pankreatitis (Bauchspeicheldrüsenentzündung)"],"unbekannt":["Nephrotisches Syndrom (Eiweissverlust über die Niere)","Pulmonale arterielle Hypertonie (Lungenhochdruck), auch Jahre nach Beginn","Medikamentenbedingter Lupus erythematodes"]},"schwangerschaft":"Kann nach ärztlicher Abwägung bei klinischem Bedarf auch während der Schwangerschaft angewendet werden; bisherige Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Nur sehr geringe Mengen gehen in die Muttermilch über und werden vom Säugling kaum aufgenommen; Stillen ist möglich.","hinweise":["Grippeähnliche Beschwerden lassen sich durch Spritzen am Abend und ein fiebersenkendes Schmerzmittel (z. B. Paracetamol) mildern; sie nehmen meist nach einigen Monaten ab.","Bei Niedergeschlagenheit oder Suizidgedanken umgehend die Ärztin oder den Arzt informieren.","Blutbild, Leber- und Schilddrüsenwerte werden regelmässig kontrolliert.","Einstichstellen wechseln; im Kühlschrank lagern."],"darreichung":["Injektionslösung (Fertigspritze, Fertigpen, Patrone)"]},"iohexol":{"wirkmechanismus":"Macht Gewebe und Gefässe im Röntgenbild sichtbar, weil die enthaltenen Jodatome Röntgenstrahlen stark abschwächen. Iohexol ist ein nichtionisches, monomeres Trijodbenzol-Derivat mit niedriger Osmolalität, was die Verträglichkeit verbessert. Nach der Injektion verteilt es sich im Extrazellulärraum, wird kaum an Eiweiss gebunden und unverändert über die Nieren ausgeschieden (Halbwertszeit etwa 2 Stunden bei normaler Nierenfunktion).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen nach Gabe in den Rückenmarkskanal (Myelographie)"],"haeufig":["Wärme- oder Hitzegefühl bei der Injektion"],"gelegentlich":["Übelkeit"],"selten":["Überempfindlichkeitsreaktionen (Ausschlag, Nesselsucht, Juckreiz, Atemnot, Bronchospasmus, Kehlkopfschwellung)","Kopfschmerzen nach Injektion in die Blutgefässe","Erbrechen","Bradykardie (verlangsamter Puls)","Nierenfunktionsstörung bis zum akuten Nierenversagen","Fieber"],"sehrSelten":["Blutdruckanstieg oder -abfall","Geschmacksstörung","Durchfall"],"unbekannt":["Anaphylaktischer Schock","Krampfanfälle, vorübergehende Kontrastmittel-Enzephalopathie (Verwirrtheit, Sehstörungen)","Schwere Herzkomplikationen (Herzrhythmusstörungen, Herzstillstand)","Schilddrüsenüberfunktion (Thyreotoxikose) oder vorübergehende Unterfunktion","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt nötig ist; das Jod kann die Schilddrüse des Ungeborenen beeinflussen.","stillzeit":"Geht nur in sehr geringer Menge in die Muttermilch über; das Stillen kann normal fortgesetzt werden.","hinweise":["Vor der Untersuchung frühere Kontrastmittelreaktionen, Allergien, Nieren- und Schilddrüsenerkrankungen sowie die Einnahme von Metformin angeben.","Vor und nach der Untersuchung ausreichend trinken, sofern ärztlich nicht anders verordnet.","Nach der Injektion mindestens 30 Minuten in der Nähe des Untersuchungsorts bleiben; verzögerte Hautreaktionen können bis zu einer Woche später auftreten und sollten gemeldet werden."],"darreichung":["Injektionslösung","Lösung zum Einnehmen oder zur Anwendung in Körperhöhlen"]},"iopromid":{"wirkmechanismus":"Macht Gewebe und Gefässe im Röntgenbild sichtbar, weil die enthaltenen Jodatome Röntgenstrahlen stark abschwächen. Iopromid ist ein nichtionisches, monomeres Trijodbenzol-Derivat mit niedriger Osmolalität. Nach der Injektion verteilt es sich rasch im Extrazellulärraum und wird unverändert über die Nieren ausgeschieden (Halbwertszeit etwa 2 Stunden bei normaler Nierenfunktion).","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel, Geschmacksstörung","Übelkeit, Erbrechen","Wärmegefühl, Schmerzen und Reaktionen an der Injektionsstelle","Brustschmerzen, Blutdruckanstieg, Gefässerweiterung (Hautrötung)","Verschwommenes Sehen"],"gelegentlich":["Überempfindlichkeitsreaktionen (Nesselsucht, Juckreiz, Schwellungen, Atemnot) bis zum anaphylaktischen Schock","Kreislaufreaktionen (vasovagale Reaktion), Blutdruckabfall","Herzrhythmusstörungen","Verwirrtheit, Unruhe, Kribbeln, Schläfrigkeit","Bauchschmerzen","Ödeme (Wassereinlagerungen)"],"selten":["Herzstillstand, Durchblutungsstörung des Herzmuskels, Herzklopfen","Angst"],"unbekannt":["Schilddrüsenüberfunktion bis zur thyreotoxischen Krise","Krampfanfälle, Schlaganfall, vorübergehende Erblindung, Kontrastmittel-Enzephalopathie","Akutes Nierenversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)"]},"schwangerschaft":"Nur anwenden, wenn die Untersuchung unbedingt nötig ist; das Jod kann die Schilddrüse des Ungeborenen beeinflussen.","stillzeit":"Geht nur in sehr geringer Menge in die Muttermilch über; ein Risiko für den Säugling ist nicht zu erwarten.","hinweise":["Vor der Untersuchung frühere Kontrastmittelreaktionen, Allergien, Nieren- und Schilddrüsenerkrankungen sowie die Einnahme von Metformin angeben.","Vor und nach der Untersuchung ausreichend trinken, sofern ärztlich nicht anders verordnet.","Nach der Injektion mindestens 30 Minuten in der Nähe des Untersuchungsorts bleiben; verzögerte Hautreaktionen können bis zu einer Woche später auftreten und sollten gemeldet werden."],"darreichung":["Injektions- und Infusionslösung"]},"ipratropium":{"wirkmechanismus":"Entspannt die Bronchialmuskulatur bzw. vermindert die Sekretbildung in der Nase. Ipratropium blockiert Muskarinrezeptoren und hemmt so die Wirkung des Nervenbotenstoffs Acetylcholin, der die Bronchien verengt und die Drüsen der Nasenschleimhaut anregt. Als quaternäre Ammoniumverbindung wird es kaum ins Blut aufgenommen und wirkt vor allem dort, wo es angewendet wird. Die Wirkung beginnt nach etwa 15 Minuten und hält einige Stunden an.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Schwindel","Husten, Rachenreizung","Mundtrockenheit, Übelkeit, Störungen der Magen-Darm-Beweglichkeit","Beim Nasenspray: trockene Nase, Nasenbluten, Reizung der Nasenschleimhaut"],"gelegentlich":["Überempfindlichkeitsreaktionen, Anaphylaxie","Augenbeschwerden: verschwommenes Sehen, erweiterte Pupillen, erhöhter Augeninnendruck, Glaukom, Augenschmerzen, Farbringe um Lichter","Herzklopfen, supraventrikuläre Tachykardie (Herzrasen)","Bronchospasmus, paradoxer Bronchospasmus, Kehlkopfkrampf, Rachenschwellung","Durchfall, Verstopfung, Erbrechen, Mundschleimhautentzündung","Hautausschlag, Juckreiz, Angioödem","Harnverhalt"],"selten":["Akkommodationsstörungen (Probleme beim Scharfstellen)","Vorhofflimmern, erhöhte Herzfrequenz","Nesselsucht"]},"schwangerschaft":"Keine Hinweise auf Fruchtschädigung, aber begrenzte Erfahrungen; besonders im 1. Drittel nur nach ärztlicher Nutzen-Risiko-Abwägung.","stillzeit":"Nicht bekannt, ob Ipratropium in die Muttermilch übergeht (bei Inhalation wenig wahrscheinlich in relevanter Menge); Anwendung nach ärztlicher Abwägung.","hinweise":["Sprühnebel und Inhalationslösung nicht in die Augen bringen; bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall).","Bei plötzlich zunehmender Atemnot oder ungenügender Wirkung sofort ärztliche Hilfe holen.","Das Nasenspray hilft gegen Naselaufen, nicht gegen eine verstopfte Nase."],"darreichung":["Dosieraerosol","Lösung zur Inhalation (Einzeldosen für Vernebler)","Nasenspray"]},"ipratropium-fenoterol":{"wirkmechanismus":"Erweitert verengte Bronchien rasch über zwei verschiedene Mechanismen. Ipratropium blockiert die Muskarinrezeptoren der Bronchialmuskulatur und verhindert so die verengende Wirkung des Nervenbotenstoffs Acetylcholin. Fenoterol stimuliert die Beta-2-Rezeptoren und entspannt dadurch die Bronchialmuskulatur. Die Kombination wirkt innerhalb weniger Minuten; die Wirkung hält einige Stunden an.","nebenwirkungen":{"haeufig":["Husten"],"gelegentlich":["Kopfschmerzen, Schwindel","Zittern (Tremor), Nervosität","Herzrasen (Tachykardie), Herzklopfen","Rachenentzündung, Heiserkeit","Übelkeit, Erbrechen, Mundtrockenheit","Anstieg des oberen (systolischen) Blutdrucks"],"selten":["Herzrhythmusstörungen (z. B. Vorhofflimmern), Durchblutungsstörung des Herzmuskels (Myokardischämie)","Paradoxer Bronchospasmus, Kehlkopfkrampf, Rachenreizung","Nesselsucht, Hautausschlag, Juckreiz, Angioödem","Harnverhalt","Muskelkrämpfe, Muskelschwäche, Muskelschmerzen","Mundschleimhautentzündung, Durchfall, Verstopfung"],"unbekannt":["Hypokaliämie (Kaliummangel)","Anaphylaxie (schwere allergische Reaktion)","Augenbeschwerden: verschwommenes Sehen, erweiterte Pupillen, erhöhter Augeninnendruck, akutes Glaukom","Unruhe, psychische Störungen"]},"schwangerschaft":"Nur nach ärztlicher Nutzen-Risiko-Abwägung, besonders im 1. Drittel. Fenoterol kann gegen Ende der Schwangerschaft die Wehentätigkeit hemmen.","stillzeit":"Fenoterol geht in die Muttermilch über; für Ipratropium fehlen Daten. Anwendung nur nach ärztlicher Abwägung.","hinweise":["Bei plötzlich zunehmender Atemnot oder ungenügender Wirkung sofort ärztliche Hilfe holen – nicht eigenmächtig höher dosieren.","Sprühnebel und Inhalationslösung nicht in die Augen bringen; bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall).","Wer das Spray regelmässig braucht, benötigt bei Asthma zusätzlich eine entzündungshemmende Dauertherapie."],"darreichung":["Dosieraerosol","Lösung zur Inhalation (für Vernebler)"]},"irbesartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II an seinem Rezeptor blockiert. Irbesartan ist ein direkt wirksamer, selektiver Antagonist am AT1-Rezeptor: Die Gefässe weiten sich, die Aldosteronausschüttung sinkt, und die Niere scheidet mehr Salz und Wasser aus. Bei Diabetes mit Nierenschaden verlangsamt es das Fortschreiten der Nierenerkrankung. Irbesartan wird in der Leber (Glucuronidierung, CYP2C9) abgebaut und hat eine lange Halbwertszeit, sodass eine Einnahme pro Tag genügt.","nebenwirkungen":{"sehrHaeufig":["Hyperkaliämie (erhöhtes Kalium) – vor allem bei Diabetes mit Nierenschaden"],"haeufig":["Schwindel, auch beim Aufstehen","Blutdruckabfall beim Aufstehen (vor allem bei Diabetes mit Nierenschaden)","Übelkeit, Erbrechen","Müdigkeit","Muskel- und Knochenschmerzen","Anstieg der Kreatinkinase (Muskelenzym), leichter Abfall des Hämoglobins"],"gelegentlich":["Beschleunigter Puls (Tachykardie)","Flush (Gesichtsrötung)","Husten","Durchfall, Verdauungsstörungen, Sodbrennen","Brustschmerzen","Sexuelle Funktionsstörungen","Gelbsucht (Ikterus)"],"unbekannt":["Thrombozytopenie, Anämie","Überempfindlichkeitsreaktionen: Angioödem, Hautausschlag, Nesselsucht, Anaphylaxie","Hypoglykämie (Unterzuckerung)","Kopfschmerzen, Drehschwindel, Ohrensausen, Geschmacksstörung","Hepatitis, Leberfunktionsstörung","Leukozytoklastische Vaskulitis (Gefässentzündung der Haut)","Gelenk- und Muskelschmerzen, Muskelkrämpfe","Nierenfunktionsstörung bis Nierenversagen"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen; im 2. und 3. Drittel kontraindiziert, da fruchtschädigend (Nierenschäden, Fruchtwassermangel, verzögerte Schädelverknöcherung). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch ärztlich auf ein anderes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten zum Übergang in die Muttermilch fehlen; besser untersuchte Alternativen wählen.","hinweise":["Einmal täglich, unabhängig von den Mahlzeiten.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel und Kaliumpräparate nur nach ärztlicher Rücksprache.","Zu Beginn kann Schwindel auftreten – Vorsicht beim Autofahren.","Bei starkem Durchfall, Erbrechen oder Flüssigkeitsmangel ärztlich klären, ob die Einnahme vorübergehend pausiert werden soll."],"darreichung":["Filmtabletten"]},"irinotecan":{"wirkmechanismus":"Verhindert, dass Krebszellen ihr Erbgut verdoppeln können. Irinotecan ist eine Vorstufe (Prodrug): Carboxylesterasen wandeln es in den 100- bis 1000-fach wirksameren Metaboliten SN-38 um. SN-38 hemmt die Topoisomerase I und stabilisiert deren Komplex mit der DNA, sodass bei der DNA-Verdoppelung Strangbrüche entstehen und die Zelle abstirbt. SN-38 wird durch das Enzym UGT1A1 abgebaut; Menschen mit verminderter UGT1A1-Aktivität (z. B. bei Morbus Meulengracht) sind empfindlicher.","nebenwirkungen":{"sehrHaeufig":["Schwerer verzögerter Durchfall (ab 24 Stunden nach der Infusion)","Neutropenie, Anämie","Übelkeit, Erbrechen","Haarausfall (vorübergehend)","Fieber ohne Infektion","Schwäche (Asthenie)","Appetitlosigkeit"],"haeufig":["Akutes cholinerges Syndrom (Frühdurchfall, Schwitzen, Bauchkrämpfe, Speichelfluss, Sehstörungen, Tränenfluss)","Thrombozytopenie (Mangel an Blutplättchen)","Infektionen, febrile Neutropenie","Verstopfung","Vorübergehender Anstieg von Leberwerten, Bilirubin oder Kreatinin"],"gelegentlich":["Interstitielle Lungenerkrankung (Lungeninfiltrate)","Leichte allergische Reaktionen","Nierenfunktionsstörung bis Nierenversagen bei Austrocknung"],"selten":["Anaphylaktische Reaktionen","Kolitis (Dickdarmentzündung), auch pseudomembranös","Darmverschluss, Magen-Darm-Blutungen"],"unbekannt":["Sepsis","Hypokaliämie, Hyponatriämie (meist durch Durchfall und Erbrechen)","Darmperforation","Thromboembolische Ereignisse"]},"schwangerschaft":"Im Tierversuch fruchtschädigend; in der Schwangerschaft nicht anwenden. Frauen und Männer müssen während und mehrere Monate nach der Behandlung sicher verhüten.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Bei verzögert einsetzendem Durchfall sofort das verordnete Mittel (meist Loperamid) nach Anweisung einnehmen, viel trinken und die Ärztin oder den Arzt informieren – bei Fieber oder anhaltendem Durchfall sofort.","Johanniskraut und Lebendimpfungen sind während der Behandlung nicht erlaubt.","Schwindel und Sehstörungen sind in den ersten 24 Stunden möglich – dann nicht Auto fahren.","Campto und Onivyde sind nicht austauschbar; Blutbild vor jedem Zyklus."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Liposomales Konzentrat zur Herstellung einer Infusionsdispersion"]},"isoniazid":{"wirkmechanismus":"Hemmt den Aufbau der Zellwand von Tuberkulosebakterien und tötet sich teilende Bakterien ab. Isoniazid ist ein Prodrug: Das bakterielle Enzym KatG aktiviert es, das aktive Produkt blockiert die Enoyl-ACP-Reduktase (InhA) und damit die Synthese der Mykolsäuren, eines Hauptbestandteils der Mykobakterien-Zellwand. Der Abbau erfolgt in der Leber durch Acetylierung (NAT2); bei «Langsam-Acetylierern» sind die Spiegel höher und Nebenwirkungen häufiger. Isoniazid hemmt zudem den Vitamin-B6-Stoffwechsel, was Nervenschäden begünstigt.","nebenwirkungen":{"sehrHaeufig":["Leichter, meist vorübergehender Anstieg der Leberwerte"],"haeufig":["Periphere Neuropathie (Kribbeln, Brennen, Taubheit an Händen und Füssen), dosisabhängig","Übelkeit, Erbrechen, Oberbauchbeschwerden"],"gelegentlich":["Hepatitis (Leberentzündung), häufiger mit zunehmendem Alter","Hautausschlag, Juckreiz","Schwindel, Kopfschmerzen"],"selten":["Schwere, teils tödliche Hepatitis und Leberversagen","Agranulozytose, Thrombozytopenie, hämolytische und sideroblastische Anämie","Krampfanfälle","Optikusneuritis (Sehnerventzündung)","Psychosen, Verwirrtheit, Gedächtnisstörungen","Arzneimittelfieber, Lupus-ähnliches Syndrom"],"unbekannt":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Pellagra (Vitamin-B3-Mangel mit Hautentzündung)","Hyperglykämie (erhöhter Blutzucker)","Gynäkomastie (Brustvergrösserung beim Mann)","Pankreatitis"]},"schwangerschaft":"Zur Behandlung einer Tuberkulose nach ärztlicher Abwägung möglich, zusammen mit Vitamin B6 (Pyridoxin). Erhöhtes Hepatitis-Risiko in der Schwangerschaft und kurz nach der Geburt beachten.","stillzeit":"Geht in die Muttermilch über; Stillen ist in der Regel möglich. Mutter erhält Vitamin B6, das Kind wird auf Gelbsucht und Nervenreizungen beobachtet.","hinweise":["Auf nüchternen Magen einnehmen (mindestens 1 Stunde vor oder 2 Stunden nach dem Essen).","Alkohol meiden – er erhöht das Risiko für Leberschäden.","Lebensmittel mit viel Tyramin oder Histamin (gereifter Käse, Thunfisch, Makrele, Rotwein) können Kopfschmerzen, Herzklopfen, Hautrötung und Schwitzen auslösen.","Bei Appetitlosigkeit, Übelkeit, Müdigkeit, dunklem Urin oder Gelbsucht sofort ärztlich melden; Leberwerte regelmässig kontrollieren lassen."],"darreichung":["Tabletten"]},"isosorbiddinitrat":{"wirkmechanismus":"Erweitert die Blutgefässe und entlastet so das Herz. Isosorbiddinitrat setzt in der Gefässwand Stickstoffmonoxid (NO) frei, das über die Bildung von cGMP die glatte Gefässmuskulatur erschlaffen lässt. Vor allem die Venen werden weiter: Weniger Blut fliesst zum Herzen zurück, Wandspannung und Sauerstoffbedarf des Herzmuskels sinken. Zusätzlich werden Arterien und Herzkranzgefässe erweitert. Bei Dauertherapie ohne nitratfreies Intervall lässt die Wirkung nach (Nitrattoleranz).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (vor allem zu Beginn)"],"haeufig":["Schwindel, Benommenheit, Schläfrigkeit","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Herzrasen (reflektorische Tachykardie)","Schwäche"],"gelegentlich":["Kreislaufkollaps, Ohnmacht (Synkope)","Verstärkte Angina-pectoris-Beschwerden","Übelkeit, Erbrechen","Gesichtsrötung (Flush)","Allergische Hautreaktionen"],"sehrSelten":["Sodbrennen"],"unbekannt":["Exfoliative Dermatitis (schwere Hautschuppung)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nitrate können in die Muttermilch übergehen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Spray im Sitzen anwenden (Schwindel, Ohnmacht möglich); bessern sich die Brustschmerzen nicht innert weniger Minuten, sofort den Notruf 144 wählen.","Retardtabletten unzerkaut einnehmen; ein tägliches nitratfreies Intervall (meist nachts) beugt dem Wirkungsverlust vor.","Keine Potenzmittel (PDE-5-Hemmer) einnehmen; Alkohol verstärkt den Blutdruckabfall.","Kopfschmerzen zu Beginn klingen meist nach einigen Tagen ab."],"darreichung":["Spray zur Anwendung in der Mundhöhle","Retardtabletten","Infusionslösung"]},"isosorbidmononitrat":{"wirkmechanismus":"Erweitert die Blutgefässe und entlastet so das Herz. Isosorbidmononitrat setzt in der Gefässwand Stickstoffmonoxid (NO) frei, das über cGMP die glatte Gefässmuskulatur erschlaffen lässt; vor allem die Venen werden weiter, sodass Rückstrom zum Herzen, Wandspannung und Sauerstoffbedarf des Herzmuskels abnehmen. Es ist der wirksame Hauptmetabolit von Isosorbiddinitrat, wird aber vollständig und ohne Abbau in der Leber aufgenommen. Bei Dauereinnahme ohne nitratfreies Intervall lässt die Wirkung nach (Nitrattoleranz).","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (vor allem zu Beginn)"],"haeufig":["Schwindel, Benommenheit, Schläfrigkeit","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Herzrasen (reflektorische Tachykardie)","Schwäche, Müdigkeit"],"gelegentlich":["Kreislaufkollaps, Ohnmacht (Synkope)","Verstärkte Angina-pectoris-Beschwerden","Übelkeit, Erbrechen","Gesichtsrötung (Flush)","Allergische Hautreaktionen"],"sehrSelten":["Sodbrennen"],"unbekannt":["Exfoliative Dermatitis (schwere Hautschuppung)"]},"schwangerschaft":"Begrenzte Erfahrungen; nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nitrate können in die Muttermilch übergehen; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nicht für den akuten Anfall geeignet – dafür ein schnell wirksames Nitrat (Spray oder Kapsel) bereithalten.","Täglich ein nitratfreies Intervall einhalten (z. B. Retardtablette morgens), sonst lässt die Wirkung nach.","Keine Potenzmittel (PDE-5-Hemmer) einnehmen; Alkohol verstärkt den Blutdruckabfall.","Nicht abrupt absetzen (Gefahr vermehrter Angina-pectoris-Anfälle)."],"darreichung":["Tabletten","Retardtabletten"]},"isotretinoin":{"wirkmechanismus":"Verkleinert die Talgdrüsen und vermindert die Talgproduktion drastisch, sodass Mitesser und entzündete Pickel abheilen. Isotretinoin (13-cis-Retinsäure) ist ein Vitamin-A-Abkömmling, der die Vermehrung und Reifung der Talgdrüsenzellen hemmt und die Verhornung in den Haarfollikeln normalisiert. Dadurch nimmt indirekt auch die Besiedelung mit Aknebakterien ab; zudem wirkt es entzündungshemmend. Der genaue Mechanismus ist nicht vollständig geklärt; ein Teil wird im Körper zu Tretinoin und 4-Oxo-Isotretinoin umgewandelt.","nebenwirkungen":{"sehrHaeufig":["Trockene, rissige Lippen (Cheilitis)","Trockene, schuppende, juckende Haut, Hautausschlag, verletzliche Haut","Trockene, gereizte Augen, Bindehaut- und Lidrandentzündung","Gelenk-, Muskel- und Rückenschmerzen","Erhöhte Leberwerte (Transaminasen)","Erhöhte Triglyceride, vermindertes HDL-Cholesterin","Blutbildveränderungen (Anämie, zu viele oder zu wenige Blutplättchen)"],"haeufig":["Kopfschmerzen","Nasenbluten, trockene Nase, Entzündung von Nase und Rachen","Erhöhtes Cholesterin, erhöhter Blutzucker","Neutropenie (Mangel an weissen Blutkörperchen)","Blut oder Eiweiss im Urin"],"selten":["Depression, Verschlechterung einer Depression, Angst, Aggressivität, Stimmungsschwankungen","Haarausfall","Allergische Reaktionen, Anaphylaxie"],"sehrSelten":["Suizidgedanken, Suizidversuch, Psychosen","Erhöhter Hirndruck (Pseudotumor cerebri) mit starken Kopfschmerzen, Übelkeit, Sehstörungen","Pankreatitis (Bauchspeicheldrüsenentzündung), Hepatitis","Chronisch entzündliche Darmerkrankung, Darmblutungen","Sehstörungen: verminderte Nachtsicht, Hornhauttrübung, Katarakt","Lichtempfindlichkeit der Haut (Photosensibilität)","Sehnenentzündung, Knochenveränderungen, vorzeitiger Schluss der Wachstumsfugen","Krampfanfälle, Hörstörungen"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Rhabdomyolyse (Muskelzerfall)","Sexuelle Funktionsstörungen (Erektionsstörung, verminderte Libido)"]},"schwangerschaft":"Absolut kontraindiziert: stark fruchtschädigend schon bei kurzer Einnahme. Frauen müssen ab 1 Monat vor bis 1 Monat nach der Behandlung sicher verhüten (Schwangerschaftsverhütungsprogramm mit Schwangerschaftstests). Auch das Gel ist in der Schwangerschaft kontraindiziert.","stillzeit":"Kontraindiziert; Isotretinoin geht in die Muttermilch über.","hinweise":["Frauen: sichere Verhütung ab 1 Monat vor Beginn bis 1 Monat nach Ende der Behandlung, regelmässige Schwangerschaftstests; die Gestagen-Minipille allein gilt nicht als ausreichend.","Stimmungsveränderungen, Niedergeschlagenheit oder Suizidgedanken sofort ärztlich melden.","Während und bis 1 Monat nach der Behandlung kein Blut spenden und Kapseln nie weitergeben; Leberwerte und Blutfette werden regelmässig kontrolliert.","Lippen und Haut pflegen, Sonnenschutz verwenden; Wachsepilation, Dermabrasion und Laserbehandlungen während und bis 6 Monate nach der Behandlung meiden."],"darreichung":["Weichkapseln","Gel (Kombination mit Erythromycin)"]},"itraconazol":{"wirkmechanismus":"Hemmt die Bildung eines wichtigen Bausteins der Pilzzellwand und stoppt so das Pilzwachstum. Itraconazol blockiert die pilzeigene Lanosterol-14α-Demethylase (ein Cytochrom-P450-Enzym), sodass kein Ergosterol mehr für die Zellmembran entsteht. Es reichert sich in Haut, Nägeln und Fettgewebe an und wirkt dort noch Wochen nach Therapieende. Itraconazol und sein Hauptmetabolit hemmen zudem stark das menschliche CYP3A4 und P-Glykoprotein – daher sind viele Medikamente gleichzeitig verboten.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bauchschmerzen, Übelkeit"],"gelegentlich":["Infektionen der oberen Atemwege, Schnupfen, Nebenhöhlenentzündung","Überempfindlichkeitsreaktionen","Durchfall, Erbrechen, Verstopfung, Verdauungsbeschwerden, Blähungen, Geschmacksstörung","Abnorme Leberwerte, erhöhtes Bilirubin","Hautausschlag, Juckreiz, Nesselsucht","Menstruationsstörungen"],"selten":["Leukopenie (Mangel an weissen Blutkörperchen)","Anaphylaxie, Angioödem, Serumkrankheit","Kribbeln, Taubheitsgefühl, periphere Neuropathie","Sehstörungen (verschwommenes Sehen, Doppelbilder), Tinnitus, Hörverlust","Herzinsuffizienz (Herzschwäche) mit Atemnot und Ödemen","Pankreatitis","Schwere Leberschäden bis akutes Leberversagen","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, AGEP), Haarausfall, Lichtempfindlichkeit"],"unbekannt":["Hypokaliämie (Kaliummangel), erhöhte Triglyceride","Ödeme","Erektionsstörung","Häufiges Wasserlassen"]},"schwangerschaft":"Kontraindiziert, ausser bei lebensbedrohlichen Pilzinfektionen. Frauen im gebärfähigen Alter verhüten bis zur ersten Menstruation nach Behandlungsende.","stillzeit":"Geht in kleinen Mengen in die Muttermilch über. Nur nach strenger Nutzen-Risiko-Abwägung; im Zweifel nicht stillen.","hinweise":["Kapseln direkt nach einer vollständigen Mahlzeit schlucken; die Lösung dagegen nüchtern (mindestens 1 Stunde vor dem Essen) einnehmen – die beiden Formen sind nicht austauschbar.","Vor jedem neuen Medikament die Itraconazol-Behandlung erwähnen: viele Kombinationen sind verboten.","Bei Atemnot, ungewöhnlicher Gewichtszunahme, geschwollenen Beinen, Gelbsucht, dunklem Urin oder starker Müdigkeit sofort ärztlich melden.","Bei längerer Behandlung Leberwerte kontrollieren."],"darreichung":["Kapseln","Lösung zum Einnehmen"]},"ivabradin":{"wirkmechanismus":"Verlangsamt den Herzschlag, damit das Herz weniger Sauerstoff braucht und sich länger füllen kann. Ivabradin hemmt selektiv den If-Strom (HCN-Kanäle) in den Schrittmacherzellen des Sinusknotens, der die Geschwindigkeit der spontanen Erregungsbildung bestimmt. Anders als Betablocker oder Calciumantagonisten beeinflusst es weder Kontraktionskraft noch AV-Überleitung noch Blutdruck. Weil ähnliche Kanäle in der Netzhaut vorkommen, kann es vorübergehende Lichterscheinungen (Phosphene) auslösen. Ivabradin wird über CYP3A4 abgebaut.","nebenwirkungen":{"sehrHaeufig":["Lichterscheinungen (Phosphene: vorübergehende Helligkeitswahrnehmungen im Gesichtsfeld)"],"haeufig":["Kopfschmerzen (v. a. im ersten Monat), Schwindel","Verschwommenes Sehen","Bradykardie (verlangsamter Herzschlag), AV-Block 1. Grades, ventrikuläre Extrasystolen","Vorhofflimmern","Unkontrollierter Blutdruck"],"gelegentlich":["Doppelbilder, Sehstörungen","Ohnmacht (Synkope), Drehschwindel","Herzklopfen, supraventrikuläre Extrasystolen, Blutdruckabfall","Verlängerte QT-Zeit im EKG","Übelkeit, Verstopfung, Durchfall, Bauchschmerzen","Atemnot, Muskelkrämpfe, Müdigkeit","Angioödem, Hautausschlag","Eosinophilie, erhöhte Harnsäure, erhöhtes Kreatinin"],"selten":["Hautrötung, Juckreiz, Nesselsucht","Unwohlsein"],"sehrSelten":["AV-Block 2. und 3. Grades","Sinusknotensyndrom"]},"schwangerschaft":"Kontraindiziert: In Tierversuchen traten Fehlbildungen des Herzens auf. Frauen im gebärfähigen Alter müssen zuverlässig verhüten.","stillzeit":"Kontraindiziert; wer Ivabradin braucht, muss abstillen.","hinweise":["Morgens und abends zu einer Mahlzeit einnehmen; keinen Grapefruitsaft trinken.","Lichterscheinungen treten vor allem in den ersten zwei Monaten auf – vorsichtig bei Nachtfahrten oder plötzlichen Lichtwechseln.","Puls regelmässig kontrollieren: dauerhaft unter 50 Schlägen pro Minute oder Schwindel, Müdigkeit, Herzstolpern ärztlich melden.","Bei Herzklopfen oder unregelmässigem Puls an Vorhofflimmern denken und ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"ivermectin":{"wirkmechanismus":"Lähmt und tötet Würmer und Milben. Ivermectin bindet an glutamatgesteuerte Chloridkanäle in Nerven- und Muskelzellen wirbelloser Tiere, erhöht deren Durchlässigkeit für Chlorid und blockiert so die Signalübertragung. Beim Menschen kommen diese Kanäle nicht vor, und die Blut-Hirn-Schranke hält den Wirkstoff weitgehend vom Gehirn fern. Bei Rosazea wirkt es auf der Haut entzündungshemmend und gegen Demodex-Milben.","nebenwirkungen":{"haeufig":["Brennen der Haut (Creme)"],"gelegentlich":["Hautreizung, Juckreiz, trockene Haut (Creme)","Vorübergehende Verschlechterung der Rosazea (Creme)"],"unbekannt":["Übelkeit, Erbrechen, Durchfall, Bauchschmerzen (Tabletten)","Schwindel, Schläfrigkeit, Zittern (Tabletten)","Vorübergehende Zunahme des Juckreizes bei Krätze","Erhöhte Leberwerte, Eosinophilie","Schwere Enzephalopathie bei starkem Loa-loa-Befall","Toxische epidermale Nekrolyse, Stevens-Johnson-Syndrom"]},"schwangerschaft":"Tabletten nur, wenn die Behandlung eindeutig notwendig ist. Die Creme wird in der Schwangerschaft nicht empfohlen.","stillzeit":"Ivermectin geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Tabletten mit Wasser auf nüchternen Magen einnehmen (2 Stunden vor und nach der Einnahme nichts essen).","Bei Krätze Kontaktpersonen gleichzeitig behandeln und Wäsche bei mindestens 60 °C waschen; der Juckreiz kann noch einige Wochen anhalten.","Creme einmal täglich dünn auf das Gesicht auftragen; eine Besserung zeigt sich meist erst nach einigen Wochen."],"darreichung":["Tabletten","Creme"]}});
